import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';

function isId(value: unknown): boolean {
  return /^[0-9]+$/.test(String(value ?? ''));
}

@Controller('api/v1')
export class FnSfr02112Controller {
  // 경로 충돌을 피하려고 summary를 :payrollId보다 먼저 선언한다
  @Get('/payrolls/summary')
  async getPayrollSummary(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    if (!isId(q['paydayId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일을 선택해 주세요.');
    }
    const hasDepartment = q['departmentId'] !== undefined && q['departmentId'] !== null && String(q['departmentId']) !== '';
    if (hasDepartment && !isId(q['departmentId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT COUNT(p.payroll_id) AS "employeeCount",
                COALESCE(SUM(p.total_payment_amount), 0) AS "totalPaymentAmount",
                COALESCE(SUM(p.total_deduction_amount), 0) AS "totalDeductionAmount",
                COALESCE(SUM(p.net_pay_amount), 0) AS "netPayAmount"
           FROM payroll p
           JOIN employee e ON e.employee_id = p.employee_id
          WHERE p.payday_id = CAST(:paydayId AS bigint)
            AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))`,
        {
          paydayId: String(q['paydayId']),
          departmentId: hasDepartment ? String(q['departmentId']) : null,
        },
      );
      return rows[0];
    });
  }

  @Get('/payrolls/:payrollId')
  async getPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const payrollId = req.params['payrollId'];
    if (!isId(payrollId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT payroll_id AS "payrollId",
                employee_id AS "employeeId",
                total_payment_amount AS "totalPaymentAmount",
                total_deduction_amount AS "totalDeductionAmount",
                net_pay_amount AS "netPayAmount"
           FROM payroll
          WHERE payroll_id = CAST(:payrollId AS bigint)`,
        { payrollId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PAYROLL_NOT_FOUND', '급여를 찾을 수 없습니다.');
      }
      const items = await db.query(
        `SELECT a.pay_item_id AS "payItemId",
                i.item_name AS "itemName",
                i.item_category AS "itemCategory",
                a.amount AS "amount"
           FROM payroll_item_amount a
           JOIN pay_item i ON i.pay_item_id = a.pay_item_id
          WHERE a.payroll_id = CAST(:payrollId AS bigint)
          ORDER BY i.item_category, a.payroll_item_amount_id`,
        { payrollId },
      );
      return { ...rows[0], items };
    });
  }
}

