import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Field,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

function DetailDrawer({ payrollId, role, onClose }: { payrollId: number; role: string; onClose: () => void }) {
  const detail = useData<Row>(() => call('GET', '/payrolls/' + payrollId, role), [payrollId, role]);
  const d = detail.data;
  const items = ((d?.items as Row[] | undefined) ?? []);
  return (
    <Drawer title="급여명세" onClose={onClose}>
      {detail.error ? <ErrorText text={detail.error} /> : null}
      {d ? (
        <>
          <Pairs
            items={[
              ['임직원', <RefName table="employee" role={role} value={d.employeeId} />],
              ['지급 합계', <Num value={d.totalPaymentAmount} />],
              ['공제 합계', <Num value={d.totalDeductionAmount} />],
              ['실수령액', <Num value={d.netPayAmount} />],
            ]}
          />
          <DataTable
            columns={[
              { key: 'itemCategory', label: '구분', render: (r: Row) => <Badge value={r.itemCategory} /> },
              { key: 'itemName', label: '항목명' },
              { key: 'amount', label: '금액', render: (r: Row) => <Num value={r.amount} /> },
            ]}
            rows={items}
            empty="항목 내역이 없습니다."
          />
        </>
      ) : null}
    </Drawer>
  );
}

export default function FnSfr02112Page({ role, notify }: PageProps) {
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<{ paydayId: number | string; departmentId: number | string }>({ paydayId: '', departmentId: '' });
  const [pageNo, setPageNo] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);

  const list = useData<Page | undefined>(async () => {
    if (applied.paydayId === '') return undefined;
    return call<Page>('GET', '/payrolls', role, undefined, { paydayId: applied.paydayId, page: pageNo, size: SIZE });
  }, [applied, pageNo, role]);

  const summary = useData<Row | undefined>(async () => {
    if (applied.paydayId === '') return undefined;
    return call<Row>('GET', '/payrolls/summary', role, undefined, { paydayId: applied.paydayId, departmentId: applied.departmentId });
  }, [applied, role]);

  const search = () => {
    if (paydayId === '') {
      notify('급여 지급일을 선택해 주세요.');
      return;
    }
    setPageNo(0);
    setApplied({ paydayId, departmentId });
  };

  const reset = () => {
    setPaydayId('');
    setDepartmentId('');
    setPageNo(0);
    setApplied({ paydayId: '', departmentId: '' });
  };

  const s = summary.data;
  const rows = list.data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-3">
        <h2>대상 인원</h2>
        <Num value={s?.employeeCount ?? 0} />
      </section>
      <section className="box span-3">
        <h2>지급 합계</h2>
        <Num value={s?.totalPaymentAmount ?? 0} />
      </section>
      <section className="box span-3">
        <h2>공제 합계</h2>
        <Num value={s?.totalDeductionAmount ?? 0} />
      </section>
      <section className="box span-3">
        <h2>실수령 합계</h2>
        <Num value={s?.netPayAmount ?? 0} />
      </section>
      <section className="box span-12">
        <h2>급여대장</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="급여 지급일" required>
            <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} placeholder="지급일 선택" />
          </Field>
          <Field label="주부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} placeholder="전체" />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        {summary.error ? <ErrorText text={summary.error} /> : null}
        <Band total={list.data?.total ?? 0} />
        <DataTable
          columns={[
            { key: 'employeeId', label: '임직원', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'totalPaymentAmount', label: '지급 합계', render: (r: Row) => <Num value={r.totalPaymentAmount} /> },
            { key: 'totalDeductionAmount', label: '공제 합계', render: (r: Row) => <Num value={r.totalDeductionAmount} /> },
            { key: 'netPayAmount', label: '실수령액', render: (r: Row) => <Num value={r.netPayAmount} /> },
          ]}
          rows={rows}
          onRowClick={(r: Row) => setSelected(Number(r.payrollId))}
          empty={applied.paydayId === '' ? '급여 지급일을 선택하고 조회해 주세요.' : '조회된 급여가 없습니다.'}
        />
        <Pager page={pageNo} size={SIZE} total={list.data?.total ?? 0} onPage={setPageNo} />
      </section>
      {selected !== null ? <DetailDrawer payrollId={selected} role={role} onClose={() => setSelected(null)} /> : null}
    </div>
  );
}
